/**
 * ProposalThread — historial de propuestas de una negociación (Mi Garaje, mi-garaje-lab · panel de negociación):
 * cada monto es un BidMessage de Concorde (lo tuyo en vault a la derecha, lo de la otra parte en blanco con su avatar
 * a la izquierda), con quién y a qué hora debajo, y una línea con el día cuando cambia. Lo que se pase como hijos
 * (respuestas, avisos) se agrega al final de la lista como <li>. Solo depende de React y BidMessage.
 */
import type { JSX, ReactNode } from "react";
import BidMessage from "@/concorde/components/BidMessage";

export const PROPOSAL_THREAD_CSS = String.raw`
.np__thread { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.np__thread li { justify-self: start; display: flex; align-items: flex-end; gap: 8px; justify-items: start; }
.np__thread li.is-me { justify-self: end; justify-items: end; }
.np__thread li > span { font-size: .75rem; font-weight: 600; color: #6B6878; }
.np__thread .pbidmsg b { font-size: .875rem; font-weight: 700; font-variant-numeric: tabular-nums; }
.np__thread li > div { display:grid; gap:4px; justify-items:start; }
.np__thread li.is-me > div { justify-items:end; }
.np__day { justify-self:stretch !important; display:flex !important; align-items:center; gap:12px; font-size:.75rem; font-weight:600; color:#6B6878; }
.np__day::before, .np__day::after { content:""; flex:1; height:1px; background:#E1E3E2; }
.np__avatar { flex:none; display:grid; place-items:center; width:28px; height:28px; border-radius:50%; font-size:.6875rem; font-weight:700; color:#fff; background:linear-gradient(135deg, #00DAE0, #008688); }
.np__at { font-size:.6875rem; color:#6B6878; } .np__at i { font-style:normal; color:#8460E5; }
`;

export interface ProposalThreadItem {
  /** true: propuesta tuya. */
  me: boolean;
  /** Monto ya formateado (p. ej. «US$ 13,500»). */
  amount: string;
  /** Día y hora separados por un espacio («Hoy 9:10», «Ayer 10:45»); el día arma los separadores. */
  when: string;
}

export interface ProposalThreadProps {
  /** Propuestas, de la más antigua a la más nueva. */
  items: ProposalThreadItem[];
  /** Nombre de la otra parte bajo sus montos («Vendedor», «Comprador 3»). */
  other: string;
  /** Iniciales en el avatar de la otra parte («V», «C3»). */
  initials: string;
  /** <li> extra al final del historial (respuestas, avisos). */
  children?: ReactNode;
}

export function ProposalThread({ items, other, initials, children }: ProposalThreadProps): JSX.Element {
  return <>
    <style href="concorde-proposal-thread" precedence="default">{PROPOSAL_THREAD_CSS}</style>
    <ol className="np__thread">{items.map((t, i) => {
      const [day, ...hh] = t.when.split(" "), prevDay = i ? items[i - 1].when.split(" ")[0] : "";
      return [day !== prevDay ? <li key={`d${i}`} className="np__day"><span>{day}</span></li> : null,
        <li key={i} className={t.me ? "is-me" : ""}>{t.me ? null : <span className="np__avatar" aria-hidden>{initials}</span>}
          <div><BidMessage side={t.me ? "sent" : "received"} type={t.me ? "vault" : "white"}><b>{t.amount}</b></BidMessage>
            <span className="np__at">{t.me ? "Tú" : other} · {hh.join(" ") || day}{t.me ? <i aria-label="Enviada"> ✓✓</i> : null}</span></div></li>];
    })}{children}</ol>
  </>;
}

export default ProposalThread;

"use client";

/**
 * BidMessage — Generado por Concorde
 * Fuente: Figma VOYAGER · "BidMessage" (3162:12972 / 12990 / 13002 / 12984)
 *
 * Burbuja de mensaje de puja, estilo chat. Dos lados (cola en la esquina
 * inferior del lado):
 *   · side="sent"      → derecha (cola inferior-derecha)
 *   · side="received"  → izquierda (cola inferior-izquierda)
 * Color por `type`:
 *   · "live"   → relleno naranja (#FF9639→#BE3D00) + borde gradiente, texto blanco
 *   · "vault"  → relleno morado (#19004A→#3B1782→#2E0F70), texto blanco
 *   · "white"  → relleno blanco + borde lila, texto morado #3B1782
 * `logo` (slot) para la variante con logo. `children` = el mensaje.
 * Por convención: sent → live; received → vault/white. (type por defecto según side.)
 */

import type { JSX, ReactNode } from "react";

export type BidMessageSide = "sent" | "received";
export type BidMessageType = "live" | "vault" | "white";

export interface BidMessageProps {
  /** Lado de la burbuja (default "received") */
  side?: BidMessageSide;
  /** Color (default: sent→"live", received→"vault") */
  type?: BidMessageType;
  /** Logo opcional (slot) antes del texto */
  logo?: ReactNode;
  /** Contenido del mensaje */
  children?: ReactNode;
  className?: string;
}

const STYLE_ID = "concorde-bidmessage-styles";

const BIDMESSAGE_STYLES = `
.pbidmsg {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 40px;
  max-width: 100%;
  box-sizing: border-box;
  padding: 8px 18px;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", -apple-system, sans-serif);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.3;
}
.pbidmsg__logo { display: inline-flex; align-items: center; flex-shrink: 0; }
.pbidmsg__text { white-space: nowrap; }

/* Cola según el lado */
.pbidmsg--received { border-radius: 20px 20px 20px 4px; }
.pbidmsg--sent { border-radius: 20px 20px 4px 20px; }

/* live (naranja) — sent */
.pbidmsg--live {
  border: 1.5px solid transparent;
  background-image:
    linear-gradient(180deg, var(--vmc-color-orange-gradient-start, #FF9639) 0%, var(--vmc-color-orange-gradient-mid, #EF852E) 40%, var(--vmc-color-orange-gradient-end, #BE3D00) 100%),
    linear-gradient(120deg, #ffffff 0%, var(--vmc-color-orange-gradient-light, #F4AC59) 22%, #8460E5 74.5%, #ffffff 100%);
  background-origin: border-box;
  background-clip: padding-box, border-box;
  color: #ffffff;
  box-shadow: rgba(225,108,16,0.3) 0px 2px 12px;
}

/* vault (morado) — received */
.pbidmsg--vault {
  border: none;
  background: linear-gradient(90deg, #19004A 0%, #3B1782 50%, #2E0F70 100%);
  color: #ffffff;
  box-shadow: rgba(46,15,112,0.35) 0px 4px 16px;
}

/* white (blanco, texto morado) — received */
.pbidmsg--white {
  border: 1.5px solid transparent;
  background-image:
    linear-gradient(#ffffff, #ffffff),
    linear-gradient(135deg, #CFBAFF 0%, #ffffff 35%, #AE8EFF 65%, #CFBAFF 100%);
  background-origin: border-box;
  background-clip: padding-box, border-box;
  color: #3B1782;
  box-shadow: rgba(90,53,194,0.5) 0px 2px 10px;
}
`;

let _stylesInjected = false;

export default function BidMessage({
  side = "received",
  type,
  logo,
  children = "PROPUSO US$ 25,000",
  className = "",
}: BidMessageProps): JSX.Element {
  const resolvedType: BidMessageType = type ?? (side === "sent" ? "live" : "vault");

  if (typeof document !== "undefined" && !_stylesInjected) {
    if (!document.getElementById(STYLE_ID)) {
      const el = document.createElement("style");
      el.id = STYLE_ID;
      el.textContent = BIDMESSAGE_STYLES;
      document.head.appendChild(el);
    }
    _stylesInjected = true;
  }

  const cls = ["pbidmsg", `pbidmsg--${side}`, `pbidmsg--${resolvedType}`, className].filter(Boolean).join(" ");

  return (
    <>
      <style id={`${STYLE_ID}-ssr`} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: BIDMESSAGE_STYLES }} />
      <div className={cls}>
        {logo ? <span className="pbidmsg__logo">{logo}</span> : null}
        <span className="pbidmsg__text">{children}</span>
      </div>
    </>
  );
}
